#include <iostream>
#include <iomanip>
#include <array>
#include <string_view>

constexpr size_t CARDS = 8;
constexpr size_t FACES = 4;
constexpr size_t SUITS = 2;

struct Card {
    std::string_view face;
    std::string_view suit;
};

void fillDeck(std::array<Card, CARDS>& deck,
              const std::array<std::string_view, FACES>& faces,
              const std::array<std::string_view, SUITS>& suits) {
    for (size_t i = 0; i < CARDS; ++i) {
        deck[i].face = faces[i % FACES];
        deck[i].suit = suits[i / FACES];
    }
}

void deal(const std::array<Card, CARDS>& deck, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        std::cout << std::setw(5) << deck[i].face << " of "
                  << std::left << std::setw(8) << deck[i].suit << std::right;
        if ((i + 1) % 4 == 0) {
            std::cout << "\n";
        } else {
            std::cout << "  ";
        }
    }
}

int main() {
    constexpr std::array<std::string_view, FACES> faces = {
        "Ace", "Deuce", "Three", "Four"
    };
    constexpr std::array<std::string_view, SUITS> suits = {
        "Hearts", "Diamonds"
    };

    std::array<Card, CARDS> deck{};
    fillDeck(deck, faces, suits);

    // In-place swap simulation following deterministic indices
    // Initial order: [0] Ace H, [1] Deuce H, [2] Three H, [3] Four H,
    //                [4] Ace D, [5] Deuce D, [6] Three D, [7] Four D
    // Step 0: swap(0, 1) -> deck[0]=Deuce H, deck[1]=Ace H
    // Step 1: swap(1, 1) -> no change
    // Step 2: swap(2, 5) -> deck[2]=Deuce D, deck[5]=Three H
    // Step 3: swap(3, 3) -> deck[3]=Four H
    // Step 4: swap(4, 5) -> deck[4]=Three H, deck[5]=Ace D
    // Step 5: swap(5, 5) -> deck[5]=Ace D
    // Step 6: swap(6, 7) -> deck[6]=Four D, deck[7]=Three D
    // Step 7: swap(7, 7) -> deck[7]=Three D
    const size_t target[CARDS] = {1, 1, 5, 3, 5, 5, 7, 7};
    for (size_t i = 0; i < CARDS; ++i) {
        size_t j = target[i];
        Card temp = deck[i];
        deck[i] = deck[j];
        deck[j] = temp;
    }

    deal(deck, CARDS);
    return 0;
}

#include <iostream>

union Number {
    int x;
    double y;
};

int main() {
    // Initializing union with the first member (int x)
    Number val = { 10 };
    std::cout << "val.x initialized: " << val.x << "\n";
    std::cout << "sizeof(Number): " << sizeof(Number) << "\n";
    std::cout << "sizeof(double): " << sizeof(double) << "\n";

    // Both members share the exact same base address
    void* addrX = static_cast<void*>(&val.x);
    void* addrY = static_cast<void*>(&val.y);
    std::cout << "Addresses identical: " << std::boolalpha << (addrX == addrY) << "\n";

    // Overwrite the shared storage with double member
    val.y = 100.0;
    std::cout << "val.y after update: " << val.y << "\n";
    return 0;
}
